const rawOutput = $json.output;

let data;

try {
  data = typeof rawOutput === 'string'
    ? JSON.parse(rawOutput)
    : rawOutput;
} catch (error) {
  throw new Error('AI Agent returned invalid JSON');
}

const budget = Number(data.budget);

if (!Number.isFinite(budget)) {
  throw new Error('Invalid budget received from AI Agent');
}

let priority;

if (budget >= 500000) {
  priority = 'HIGH';
} else if (budget >= 200000) {
  priority = 'MEDIUM';
} else {
  priority = 'LOW';
}

return [
  {
    json: {
      ...data,
      priority,
      status: 'New'
    }
  }
];

const data = $('Calculate Lead Priority').item.json;

let heading;

if (data.priority === 'HIGH') {
  heading = '🔥 HIGH PRIORITY CLIENT';
} else if (data.priority === 'MEDIUM') {
  heading = '⚠️ MEDIUM PRIORITY CLIENT';
} else {
  heading = '✅ STANDARD CLIENT';
}

const budgetFormatted = Number(data.budget).toLocaleString('en-PK');

return [
  {
    json: {
      slack_message: `${heading}

${data.client_name} - ${data.company}

Service: ${data.service}
Budget: PKR ${budgetFormatted}
Priority: ${data.priority}

AI Summary: ${data.summary}

Next Action: ${data.next_action}

✅ Airtable + Notion records created successfully.`
    }
  }
];
